const agents = $input.all().map(({ json }) => json);
if (agents.length === 0 || agents.some((agent) => typeof agent !== 'object' || agent === null)) throw new Error('Paperclip returned an unexpected agent list.');
const safeAgents = agents.map((agent) => ({
  name: String(agent.name ?? 'نامشخص'),
  role: String(agent.role ?? 'نامشخص'),
  status: String(agent.status ?? 'unknown'),
  heartbeatEnabled: Boolean(agent.runtimeConfig?.heartbeat?.enabled),
  monthlyBudgetCents: Number(agent.budgetMonthlyCents ?? 0),
  lastHeartbeatAt: agent.lastHeartbeatAt ?? null,
}));
const counts = Object.fromEntries([...new Set(safeAgents.map((agent) => agent.status))].map((status) => [status, safeAgents.filter((agent) => agent.status === status).length]));
return [{ json: { source: 'paperclip', companyId: '15af0af3-1b60-4bbb-8dc3-f969c2206ea4', observedAt: new Date().toISOString(), totalRoles: safeAgents.length, counts, agents: safeAgents, changesMade: false, agentRunsStarted: false } }];
